import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { MediaSlot } from './components/MediaSlot';
import { Controls } from './components/Controls';
import { PlatformSelector } from './components/PlatformSelector';
import { AssetManager } from './components/AssetManager';
import { ResultGrid } from './components/ResultGrid';
import { WelcomeModal } from './components/WelcomeModal';
import { MediaItem, GenerationResult, TextConfig, AssetItem } from './types';
import { PLATFORMS } from './constants';

export default function App() {
  const [selectedMedia, setSelectedMedia] = useState<MediaItem | null>(null);
  const [variantCount, setVariantCount] = useState(4);
  const [selectedPlatformIds, setSelectedPlatformIds] = useState<string[]>(['yt']);
  const [isProcessing, setIsProcessing] = useState(false);
  const [status, setStatus] = useState<string>('');
  const [results, setResults] = useState<GenerationResult[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showWelcome, setShowWelcome] = useState(true);

  const [textConfig, setTextConfig] = useState<TextConfig>({
    headline: 'MAKE IT VIRAL',
    kicker: 'NEW STRATEGY',
    typeStyle: 'Bold Impact',
    textColor: '#ffffff',
    accentColor: '#FACC15', // Changed default accent to yellow
    fontSize: 100,
    assets: [],
    assetPlacement: 'Top right',
    annotation: '',
    note: '',
    strikethrough: false,
    drawArrow: false,
    bgScene: ''
  });

  useEffect(() => {
    const styleId = 'flow-design-system-css';
    if (document.getElementById(styleId)) return;
    const style = document.createElement('style');
    style.id = styleId;
    style.textContent = `
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: #FACC15; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      html, body, #root { 
        margin: 0; padding: 0; width: 100%; height: 100%; 
        background: #0e0e0e; 
        font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; 
        color: white; 
        letter-spacing: 0.1px;
        -webkit-font-smoothing: antialiased;
      }
      .checkerboard {
        background-color: #1a1a1a;
        background-image: linear-gradient(45deg, #222 25%, transparent 25%), linear-gradient(-45deg, #222 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #222 75%), linear-gradient(-45deg, transparent 75%, #222 75%);
        background-size: 20px 20px;
      }
      .no-scrollbar::-webkit-scrollbar { display: none; }
      .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      .yellow-accent-border { border-color: rgba(250, 204, 21, 0.2); }
      .yellow-accent-glow { box-shadow: 0 0 15px rgba(250, 204, 21, 0.1); }
      ::selection { background: #FACC15; color: black; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleSelectMedia = async () => {
    try {
      setError(null);
      const media = await Flow.media.select({ filter: 'image' });
      if (!media) return;

      setSelectedMedia({
        mediaId: media.mediaId,
        base64: media.base64,
        mimeType: media.mimeType,
        type: 'image',
        name: media.name
      });
    } catch (err) {
      setError('Failed to select photo.');
    }
  };

  const loadImage = (base64: string, mimeType: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error('Failed to load image for compositing'));
      img.src = `data:${mimeType};base64,${base64}`;
    });
  };

  const compositeAssets = async (base64: string, mimeType: string, assets: AssetItem[]): Promise<{base64: string, mimeType: string}> => {
    if (assets.length === 0) return { base64, mimeType };

    try {
      const mainImg = await loadImage(base64, mimeType);
      const canvas = document.createElement('canvas');
      canvas.width = mainImg.width;
      canvas.height = mainImg.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('Could not create canvas context');

      ctx.drawImage(mainImg, 0, 0);

      const assetSize = canvas.width * 0.18;
      const padding = canvas.width * 0.05;

      let x = padding;
      let y = padding;

      if (textConfig.assetPlacement === 'Top right') {
        x = canvas.width - assetSize - padding;
      } else if (textConfig.assetPlacement === 'Bottom left') {
        y = canvas.height - assetSize - padding;
      } else if (textConfig.assetPlacement === 'Bottom right') {
        x = canvas.width - assetSize - padding;
        y = canvas.height - assetSize - padding;
      }

      for (let i = 0; i < assets.length; i++) {
        const assetImg = await loadImage(assets[i].base64, assets[i].mimeType);
        const ratio = assetImg.width / assetImg.height;
        let drawW = assetSize;
        let drawH = assetSize / ratio;

        if (drawH > assetSize) {
          drawH = assetSize;
          drawW = assetSize * ratio;
        }

        const currentY = y + (i * (drawH + (padding * 0.2)));
        ctx.drawImage(assetImg, x, currentY, drawW, drawH);
      }

      const resultBase64 = canvas.toDataURL(mimeType).split(',')[1];
      return { base64: resultBase64, mimeType };
    } catch (err) {
      console.error('Compositing failed', err);
      return { base64, mimeType };
    }
  };

  const handleGenerate = async () => {
    if (!selectedMedia) return;
    setIsProcessing(true);
    setError(null);
    setResults([]);

    try {
      const totalSteps = variantCount * selectedPlatformIds.length;
      let currentStep = 0;
      const generatedResults: GenerationResult[] = [];

      for (let i = 0; i < variantCount; i++) {
        for (const platformId of selectedPlatformIds) {
          try {
            currentStep++;
            const platform = PLATFORMS.find(p => p.id === platformId)!;
            setStatus(`Designing ${platform.label} (${currentStep}/${totalSteps})...`);

            const prompt = `
              A professional, high-impact social media thumbnail for ${platform.label}.
              SUBJECT: The person from the reference image. Maintain their exact likeness, facial features, and expression.
              SCENE: ${textConfig.bgScene || 'A high-energy, modern environment'} matching the theme of "${textConfig.headline}".
              VISUAL STYLE: Dramatic cinematic lighting, high contrast, punchy saturated color grade.

              COLOR THEME:
              - Headline and primary text color: Strictly ${textConfig.textColor}.
              - Accent graphics, banners, highlights, and secondary elements: Strictly ${textConfig.accentColor}.

              TYPOGRAPHY & TYPE STYLE:
              - Type Style: Use a "${textConfig.typeStyle}" typographic aesthetic. 
              - The typography MUST be always bold, high-contrast, and extremely legible.

              TEXT TO RENDER:
              - Headline: "${textConfig.headline.toUpperCase()}"
              - Kicker: "${textConfig.kicker.toUpperCase()}"

              LAYOUT RULES:
              - Position the text cleanly in the layout so it NEVER covers the person's face.
            `.trim();

            const aiResult = await Flow.generate.image({
              prompt,
              modelDisplayName: '🍌 Nano Banana 2',
              referenceImageMediaIds: [selectedMedia.mediaId],
              aspectRatio: platform.sdkRatio
            });

            const finalImage = await compositeAssets(aiResult.base64, aiResult.mimeType, textConfig.assets);

            generatedResults.push({
              base64: finalImage.base64,
              mimeType: finalImage.mimeType,
              platform: platform.label,
              platformId: platform.id,
              variantIndex: i + 1
            });

            setResults([...generatedResults]);
          } catch (itemErr) {
            console.error(`Item generation failed:`, itemErr);
          }
        }
      }

      setStatus(generatedResults.length > 0 ? 'Thumbnails forged successfully!' : 'Generation failed.');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred during generation.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      <WelcomeModal isOpen={showWelcome} onClose={() => setShowWelcome(false)} />

      <div className="w-full lg:w-[300px] border-r border-white/5 flex flex-col justify-between p-[10px] py-[12px] h-full shrink-0 overflow-y-auto dark-scrollbar z-10">
        <div className="flex flex-col gap-[24px]">
          <MediaSlot media={selectedMedia} onSelect={handleSelectMedia} isProcessing={isProcessing} />

          <PlatformSelector 
            selectedIds={selectedPlatformIds} 
            onChange={setSelectedPlatformIds} 
          />

          <AssetManager 
            assets={textConfig.assets} 
            onChange={(assets) => setTextConfig({...textConfig, assets})}
            placement={textConfig.assetPlacement}
            onPlacementChange={(val) => setTextConfig({...textConfig, assetPlacement: val})}
            isProcessing={isProcessing}
          />

          <Controls 
            count={variantCount} 
            setCount={setVariantCount} 
            textConfig={textConfig}
            setTextConfig={setTextConfig}
            onGenerate={handleGenerate} 
            isProcessing={isProcessing}
            disabled={!selectedMedia}
          />
        </div>

        <div className="mt-6 flex flex-col gap-3">
          {status && (
            <div className="p-3 bg-yellow-400/5 rounded-xl border border-yellow-400/10 animate-pulse">
              <p className="text-[11px] font-medium text-yellow-400/70 text-center tracking-wide italic">{status}</p>
            </div>
          )}
          {error && (
            <div className="p-3 bg-red-500/10 rounded-xl border border-red-500/20">
              <p className="text-[11px] font-medium text-red-400 text-center">{error}</p>
            </div>
          )}
        </div>
      </div>

      <div className="flex-1 min-w-0 p-6 overflow-y-auto dark-scrollbar bg-black/40 relative">
        <ResultGrid results={results} isProcessing={isProcessing} count={variantCount * selectedPlatformIds.length} />
      </div>
    </div>
  );
}

export interface MediaItem {
  mediaId: string;
  base64: string;
  mimeType: string;
  type: 'image' | 'video';
  name: string;
}

export interface AssetItem {
  id: string;
  base64: string;
  mimeType: string;
  name: string;
}

export interface GenerationResult {
  base64: string;
  mimeType: string;
  platform?: string;
  platformId?: string;
  variantIndex: number;
}

export type AssetPlacement = 'Top left' | 'Top right' | 'Bottom left' | 'Bottom right';

export type TypeStyle = 
  | 'Bold Impact' 
  | 'Condensed Sports' 
  | 'Clean Modern' 
  | 'Playful Rounded' 
  | 'Elegant Serif' 
  | 'Handwritten Marker' 
  | 'Retro';

export interface TextConfig {
  headline: string;
  kicker: string;
  typeStyle: TypeStyle;
  textColor: string;
  accentColor: string;
  fontSize: number;
  assets: AssetItem[];
  assetPlacement: AssetPlacement;
  annotation: string;
  note: string;
  strikethrough: boolean;
  drawArrow: boolean;
  bgScene: string;
}

import React from 'react';
import { MediaItem } from '../types';
import { IconAddPhoto, IconRefresh } from './Icons';

interface Props {
  media: MediaItem | null;
  onSelect: () => void;
  isProcessing: boolean;
}

export const MediaSlot: React.FC<Props> = ({ media, onSelect, isProcessing }) => {
  return (
    <div className="flex flex-col gap-2 items-start w-full shrink-0">
      <div className="flex items-center px-2">
        <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
          Source Media
        </span>
      </div>

      <button 
        type="button"
        onClick={(e) => {
          e.preventDefault();
          onSelect();
        }}
        disabled={isProcessing}
        aria-label="Select source media"
        className={`w-full aspect-video rounded-xl border border-dashed transition-all overflow-hidden flex items-center justify-center bg-white/5 group relative shrink-0 outline-none focus-visible:ring-1 focus-visible:ring-yellow-400/50 ${
          media ? 'border-yellow-400/30' : 'border-[#595959] hover:border-yellow-400/60'
        } ${isProcessing ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:bg-yellow-400/5'}`}
      >
        {media ? (
          <>
            <img 
              src={`data:${media.mimeType};base64,${media.base64}`} 
              className="w-full h-full object-cover pointer-events-none" 
              alt="Selected" 
            />
            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
              <IconRefresh className="w-6 h-6 text-yellow-400" />
            </div>
          </>
        ) : (
          <div className="flex flex-col items-center gap-2 pointer-events-none">
            <IconAddPhoto className="w-6 h-6 text-[#595959] group-hover:text-yellow-400/60 transition-colors" />
            <span className="text-[10px] font-medium text-[#595959] group-hover:text-yellow-400/60 transition-colors">Add your photo</span>
          </div>
        )}
      </button>
    </div>
  );
};

import React from 'react';
import { TextConfig, TypeStyle } from '../types';
import { IconRefresh, IconStars } from './Icons';
import { ColorPicker } from './ColorPicker';
import { FieldDropdown } from './FieldDropdown';

interface Props {
  count: number;
  setCount: (n: number) => void;
  textConfig: TextConfig;
  setTextConfig: (config: TextConfig) => void;
  onGenerate: () => void;
  isProcessing: boolean;
  disabled: boolean;
}

const TEXT_SWATCHES = ['#FFFFFF', '#FACC15', '#22D3EE', '#E2E8F0', '#000000'];
const ACCENT_SWATCHES = ['#FACC15', '#FF0000', '#4ADE80', '#A855F7', '#3B82F6', '#F97316'];
const TYPE_STYLE_OPTIONS: TypeStyle[] = [
  'Bold Impact', 
  'Condensed Sports', 
  'Clean Modern', 
  'Playful Rounded', 
  'Elegant Serif', 
  'Handwritten Marker', 
  'Retro'
];

const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2 mb-1">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const Controls: React.FC<Props> = ({ count, setCount, textConfig, setTextConfig, onGenerate, isProcessing, disabled }) => {
  const updateText = (key: keyof TextConfig, val: any) => {
    setTextConfig({ ...textConfig, [key]: val });
  };

  return (
    <div className="flex flex-col gap-[24px] w-full pb-4">
      {/* Design Environment */}
      <div className="flex flex-col gap-2 items-start w-full">
        <SectionLabel>Scene Description</SectionLabel>
        <div className="flex flex-col gap-2 items-start w-full">
          <div className="border border-[#595959] hover:border-yellow-400/40 rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-2 pt-[5px] w-full transition-colors focus-within:border-yellow-400/60 shrink-0">
            <p className="text-[11px] font-medium text-white/30 tracking-[0.1px]">Background / Mood</p>
            <textarea 
              value={textConfig.bgScene}
              onChange={(e) => updateText('bgScene', e.target.value)}
              className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 resize-none h-[40px] dark-scrollbar"
              placeholder="e.g., Cyberpunk Tokyo at night..."
            />
          </div>

          <div className="flex flex-col gap-1.5 w-full px-2 pt-1 shrink-0">
            <div className="flex items-center justify-between select-none">
              <span className="text-[11px] font-medium text-white/50 tracking-[0.1px]">Variants</span>
              <span className="text-[11px] font-bold text-yellow-400 tracking-[0.1px]">{count}</span>
            </div>
            <div className="w-full flex items-center h-2">
              <input 
                type="range" 
                min={2} 
                max={6} 
                step={1} 
                value={count}
                onChange={(e) => setCount(Number(e.target.value))}
                disabled={isProcessing}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Typography Content */}
      <div className="flex flex-col gap-2 items-start w-full">
        <SectionLabel>Thumbnail Copy</SectionLabel>
        <div className="flex flex-col gap-2 items-start w-full">
          <div className="border border-[#595959] hover:border-yellow-400/40 rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-2 pt-[5px] w-full transition-colors focus-within:border-yellow-400/60 shrink-0">
            <p className="text-[11px] font-medium text-white/30 tracking-[0.1px]">Kicker (Banner Text)</p>
            <input 
              type="text" 
              value={textConfig.kicker}
              onChange={(e) => updateText('kicker', e.target.value)}
              className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0"
              placeholder="e.g., CRAZY RESULTS"
            />
          </div>

          <div className="border border-[#595959] hover:border-yellow-400/40 rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-2 pt-[5px] w-full transition-colors focus-within:border-yellow-400/60 shrink-0">
            <p className="text-[11px] font-medium text-white/30 tracking-[0.1px]">Main Headline</p>
            <textarea 
              value={textConfig.headline}
              onChange={(e) => updateText('headline', e.target.value)}
              className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 resize-none h-[40px] dark-scrollbar"
              placeholder="e.g., MAKE $1000 TODAY"
            />
          </div>

          <FieldDropdown 
            label="Type Style"
            value={textConfig.typeStyle}
            options={TYPE_STYLE_OPTIONS}
            onChange={(val) => updateText('typeStyle', val)}
            className="w-full"
          />

          <div className="flex flex-col gap-2 w-full">
            <ColorPicker 
              label="Text colour"
              value={textConfig.textColor}
              onChange={(val) => updateText('textColor', val)}
              swatches={TEXT_SWATCHTE_S}
            />
            <ColorPicker 
              label="Accent colour"
              value={textConfig.accentColor}
              onChange={(val) => updateText('accentColor', val)}
              swatches={ACCENT_SWATCHES}
            />
          </div>
        </div>
      </div>

      {/* Action Button */}
      <div className="mt-2 shrink-0">
        <button
          onClick={onGenerate}
          disabled={isProcessing || disabled}
          className={`w-full h-[44px] rounded-xl font-bold tracking-tight transition-all flex items-center justify-center gap-2 px-4 select-none shadow-xl ${
            isProcessing || disabled
              ? 'bg-[#1a1a1a] border border-[#333] text-white/20 cursor-not-allowed'
              : 'bg-yellow-400 text-black hover:bg-yellow-300 active:bg-yellow-500 shadow-yellow-400/10'
          }`}
        >
          {isProcessing ? (
            <>
              <IconRefresh className="animate-spin w-4 h-4" />
              <span className="text-[13px]">Forging magic...</span>
            </>
          ) : (
            <>
              <IconStars className="w-4 h-4" />
              <span className="text-[13px]">Forge thumbnails</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
};

const TEXT_SWATCHTE_S = TEXT_SWATCHES;

import React, { useState } from 'react';
import { Flow } from 'flow-sdk';
import { GenerationResult } from '../types';
import { PLATFORMS } from '../constants';
import { IconPhotoLibrary, IconVerified, IconStars, IconDownload, IconCheckCircle } from './Icons';

interface Props {
  results: GenerationResult[];
  isProcessing: boolean;
  count: number;
}

const DownloadButton: React.FC<{ res: GenerationResult; index: number }> = ({ res, index }) => {
  const [state, setState] = useState<'idle' | 'loading' | 'success'>('idle');

  const handleDownload = async () => {
    setState('loading');
    try {
      const ext = res.mimeType.split('/')[1]?.replace('jpeg', 'jpg') || 'png';
      const platformName = res.platform?.toLowerCase().replace(/\s+/g, '_') || 'thumbnail';
      const filename = `${platformName}_v${res.variantIndex || index + 1}.${ext}`;

      await Flow.download({
        base64: res.base64,
        mimeType: res.mimeType,
        filename
      });

      setState('success');
      setTimeout(() => setState('idle'), 2000);
    } catch (err) {
      console.error('Download failed', err);
      setState('idle');
    }
  };

  return (
    <button 
      onClick={handleDownload}
      disabled={state !== 'idle'}
      className={`flex items-center gap-1.5 h-[34px] pl-3 pr-4 rounded-xl font-bold text-[11px] uppercase tracking-wider transition-all border shrink-0 ${
        state === 'success' 
          ? 'bg-green-500/10 border-green-500/30 text-green-500'
          : 'bg-white/5 border-white/10 hover:bg-yellow-400 hover:border-yellow-400 hover:text-black text-white/60 active:scale-95'
      }`}
    >
      {state === 'loading' ? (
        <span className="material-symbols-outlined text-[18px] animate-spin">refresh</span>
      ) : state === 'success' ? (
        <>
          <IconCheckCircle className="w-3.5 h-3.5" />
          <span>Saved</span>
        </>
      ) : (
        <>
          <IconDownload className="w-3.5 h-3.5" />
          <span>Export</span>
        </>
      )}
    </button>
  );
};

export const ResultGrid: React.FC<Props> = ({ results, isProcessing, count }) => {
  if (results.length === 0 && !isProcessing) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-white/20 gap-4">
        <IconPhotoLibrary className="w-16 h-16" />
        <p className="text-sm font-medium">Forged thumbnails will appear here</p>
      </div>
    );
  }

  const getRatioString = (platformId?: string) => {
    if (!platformId) return 'aspect-[16/9]';
    const p = PLATFORMS.find(p => p.id === platformId);
    if (!p) return 'aspect-[16/9]';

    if (p.ratio >= 1.7) return 'aspect-video';
    if (p.ratio >= 1.2) return 'aspect-[4/3]';
    if (p.ratio >= 0.9) return 'aspect-square';
    if (p.ratio >= 0.7) return 'aspect-[3/4]';
    return 'aspect-[9/16]';
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-8 pb-12">
      {results.map((res, i) => (
        <div 
          key={i} 
          className="group relative flex flex-col gap-3 transition-all"
        >
          <div className={`${getRatioString(res.platformId)} w-full rounded-2xl overflow-hidden border border-white/10 bg-black hover:border-white/30 transition-all shadow-2xl relative checkerboard`}>
            <img 
              src={`data:${res.mimeType};base64,${res.base64}`} 
              className="w-full h-full object-cover" 
              alt={`${res.platform} Thumbnail`} 
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
          </div>

          <div className="flex items-center justify-between px-2">
            <div className="flex flex-col min-w-0">
              <span className="text-[12px] font-bold text-white uppercase tracking-widest truncate">{res.platform}</span>
              <span className="text-[10px] text-white/40">Style Variant {res.variantIndex}</span>
            </div>
            <div className="flex items-center gap-3">
              <IconVerified className="text-yellow-400/80 w-5 h-5 shrink-0" />
              <DownloadButton res={res} index={i} />
            </div>
          </div>
        </div>
      ))}

      {isProcessing && results.length < count && Array.from({ length: Math.max(0, count - results.length) }).map((_, i) => (
        <div 
          key={`skeleton-${i}`} 
          className="aspect-video rounded-2xl bg-white/5 border border-white/5 animate-pulse flex items-center justify-center"
        >
          <IconStars className="w-12 h-12 text-white/10" />
        </div>
      ))}
