export const PlatformSelector: React.FC<Props> = ({ selectedIds, onChange }) => {
  const togglePlatform = (id: string) => {
    if (selectedIds.includes(id)) {
      if (selectedIds.length > 1) {
        onChange(selectedIds.filter(i => i !== id));
      }
    } else {
      onChange([...selectedIds, id]);
    }
  };

  return (
    <div className="flex flex-col gap-2 items-start w-full shrink-0">
      <div className="flex items-center px-2">
        <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
