      </div>

      <div className="grid grid-cols-2 gap-2 w-full">
        {PLATFORMS.map((p) => (
          <button
            key={p.id}
            onClick={() => togglePlatform(p.id)}
            className={`h-[34px] rounded-xl border px-2.5 transition-all flex items-center justify-between group overflow-hidden shrink-0 ${
              selectedIds.includes(p.id)
                ? 'bg-yellow-400 border-yellow-400 text-black'
