  // Ensure value is a valid hex for the native input
  const safeValue = value.startsWith('#') && (value.length === 7 || value.length === 4) 
    ? value 
    : '#ffffff';

  const handleNativeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange(e.target.value.toUpperCase());
  };

  const triggerPicker = () => {
    colorInputRef.current?.click();
  };

  return (
    <div className="border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-2 p-2.5 w-full transition-colors focus-within:border-yellow-400/40 shrink-0 group">
