        <p className="text-[10px] font-bold text-white/30 tracking-wider uppercase">{label}</p>
        <div className="flex items-center gap-1.5">
          <input 
            type="text" 
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="bg-transparent text-[10px] font-bold text-white/80 tracking-[0.5px] outline-none w-[55px] border-none p-0 uppercase text-right"
            placeholder="#FFFFFF"
          />
          {/* Active Preview */}
          <div 
            className="w-3 h-3 rounded-full border border-white/20 shadow-sm" 
            style={{ backgroundColor: value }} 
          />
        </div>
      </div>

      <div className="flex items-center gap-2">
        {/* Native Input Wrapper */}
        <div className="relative shrink-0">
          <input 
            ref={colorInputRef}
            type="color" 
            value={safeValue}
            onChange={handleNativeChange}
            className="absolute opacity-0 pointer-events-none w-0 h-0"
          />
          <button 
            onClick={triggerPicker}
            type="button"
            className="w-7 h-7 rounded-lg border border-[#595959] hover:border-yellow-400/40 hover:bg-white/5 transition-all flex items-center justify-center group/btn"
            title="Custom color"
