            <IconPalette className="w-3.5 h-3.5 text-white/40 group-hover/btn:text-yellow-400 transition-colors" />
          </button>
        </div>

        <div className="h-4 w-px bg-white/10 mx-0.5 shrink-0" />

        {/* Quick Swatches */}
        <div className="flex gap-1.5 flex-1 items-center overflow-x-auto no-scrollbar py-0.5">
          {swatches.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => onChange(s)}
              className={`w-5 h-5 rounded-md border transition-all hover:scale-110 active:scale-95 shrink-0 ${
                value.toLowerCase() === s.toLowerCase() 
                  ? 'border-yellow-400 ring-2 ring-yellow-400/20' 
                  : 'border-white/10 hover:border-white/30'
              }`}
              style={{ backgroundColor: s }}
              title={s}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { IconChevronDown } from './Icons';

interface Props {
  label: string;
  value: string;
  options: string[];
  onChange: (val: any) => void;
  className?: string;
}

export const FieldDropdown: React.FC<Props> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button 
        type="button" 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none"
      >
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate pr-2">{value}</span>
          <IconChevronDown className={`w-4 h-4 text-[rgba(218,220,224,0.5)] transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {isOpen && (
        <div className="absolute z-[100] top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-2xl backdrop-blur-md animate-in fade-in zoom-in duration-150 origin-top">
          <div className="max-h-48 overflow-y-auto dark-scrollbar py-1">
            {options.map((opt) => (
              <button 
                key={opt} 
                type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${
                  value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'
                }`}
                onClick={() => { 
                  onChange(opt); 
                  setIsOpen(false); 
                }}
              >
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { Flow } from 'flow-sdk';
import { AssetItem, AssetPlacement } from '../types';
import { IconPlus, IconDelete } from './Icons';
import { FieldDropdown } from './FieldDropdown';

interface Props {
  assets: AssetItem[];
  onChange: (assets: AssetItem[]) => void;
  placement: AssetPlacement;
  onPlacementChange: (val: AssetPlacement) => void;
  isProcessing: boolean;
}

const PLACEMENT_OPTIONS: AssetPlacement[] = ['Top left', 'Top right', 'Bottom left', 'Bottom right'];

export const AssetManager: React.FC<Props> = ({ assets, onChange, placement, onPlacementChange, isProcessing }) => {
  const handleAddAsset = async () => {
    if (assets.length >= 3) return;
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (!media) return;

      const newAsset: AssetItem = {
        id: Math.random().toString(36).substr(2, 9),
        base64: media.base64,
        mimeType: media.mimeType,
        name: media.name
      };

      onChange([...assets, newAsset]);
    } catch (err) {
      console.error('Failed to select asset', err);
    }
  };

  const removeAsset = (id: string) => {
    onChange(assets.filter(a => a.id !== id));
  };

  return (
    <div className="flex flex-col gap-2 items-start w-full shrink-0">
      <div className="flex items-center px-2">
        <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
          Brand Assets (Logos)
        </span>
      </div>

      <div className="flex flex-col gap-2 w-full">
        <div className="flex gap-2 w-full overflow-x-auto no-scrollbar pb-1">
          {assets.map((asset) => (
            <div key={asset.id} className="relative group shrink-0">
              <div className="w-12 h-12 rounded-xl border border-[#595959] overflow-hidden bg-white/5 checkerboard">
                <img 
                  src={`data:${asset.mimeType};base64,${asset.base64}`} 
                  className="w-full h-full object-contain p-1" 
                  alt="Asset" 
                />
              </div>
              <button 
                onClick={() => removeAsset(asset.id)}
                className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-red-500 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <IconDelete className="w-3 h-3" />
              </button>
            </div>
          ))}

          {assets.length < 3 && (
            <button
              onClick={handleAddAsset}
              disabled={isProcessing}
              className="w-12 h-12 rounded-xl border border-dashed border-[#595959] hover:border-[#7a7a7a] transition-colors flex items-center justify-center bg-white/5 hover:bg-white/10 shrink-0"
            >
              <IconPlus className="w-5 h-5 text-[#595959]" />
            </button>
          )}
        </div>

        <FieldDropdown 
          label="Placement"
          value={placement}
          options={PLACEMENT_OPTIONS}
          onChange={onPlacementChange}
          className="w-full"
        />
      </div>
    </div>
  );
};

